extern "C" {
void pathfinder_kernel(int32_t *dst, int32_t *src, int32_t *wall, int32_t t){
	#pragma HLS inline off

	int32_t tt,n, min;

L1:	KERNEL_TILE:for(tt = 0; tt < TILE_SIZE; tt++){
#pragma HLS pipeline II=auto{_PIPE_L1}
#pragma HLS unroll factor=auto{_UNROLL_L1}
L2:		KERNEL_INNER: for(n = 0; n < COLS; n++){
#pragma HLS pipeline II=auto{_PIPE_L2}
#pragma HLS unroll factor=auto{_UNROLL_L2}
			min = dst[n];

			if(n > 0){
				min = MIN(min,dst[n-1]);
			}

			if(n < COLS-1){
				min = MIN(min,dst[n+1]);
			}

			if(t * TILE_SIZE + tt < ROWS-1){
				src[n] = wall[tt * COLS + n]+min;	
			}
		}

L3:		KERNEL_SWAP:for(n = 0; n < COLS/2; n++){
#pragma HLS pipeline II=auto{_PIPE_L3}
#pragma HLS unroll factor=auto{_UNROLL_L3}
			dst[2*n] = src[2*n];
			dst[2*n+1] = src[2*n+1];
		}
	}
}

void load(int32_t *wall, int32_t *J, int32_t t){
	#pragma HLS inline off

	memcpy(wall,J + COLS*(t*TILE_SIZE+1),sizeof(int32_t) * COLS * TILE_SIZE);
}

